package main

import (
	"fmt"
	"log"
	"net/http"
	"time"
)

// responseRecorder wraps ResponseWriter to capture the status code
type responseRecorder struct {
	http.ResponseWriter
	code int
}

func (rr *responseRecorder) WriteHeader(code int) {
	rr.code = code
	rr.ResponseWriter.WriteHeader(code)
}

// loggingMiddleware logs method, path, status, and duration
func loggingMiddleware(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		start := time.Now()
		rec := &responseRecorder{ResponseWriter: w, code: http.StatusOK}

		next.ServeHTTP(rec, r)

		log.Printf("%s %s -> %d (%v)", r.Method, r.URL.Path, rec.code, time.Since(start))
	})
}

// TODO: implement corsMiddleware that:
// - sets Access-Control-Allow-Origin to "*"
// - sets Access-Control-Allow-Methods
// - handles OPTIONS preflight with 204
func corsMiddleware(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Access-Control-Allow-Origin", "*")
		w.Header().Set("Access-Control-Allow-Methods", "GET, POST, DELETE, OPTIONS")
		w.Header().Set("Access-Control-Allow-Headers", "Content-Type, Authorization")

		if r.Method == http.MethodOptions {
			w.WriteHeader(http.StatusNoContent)
			return
		}
		next.ServeHTTP(w, r)
	})
}

func apiHandler(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Content-Type", "application/json")
	fmt.Fprintln(w, `{"status": "ok"}`)
}

func main() {
	mux := http.NewServeMux()
	mux.HandleFunc("/api", apiHandler)

	handler := corsMiddleware(loggingMiddleware(mux))

	fmt.Println("Server on :8080")
	http.ListenAndServe(":8080", handler)
}
